import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from '../remotionShim';
import { Pie } from "@remotion/shapes";

{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }




export type ParetoPrincipleProps = Record<string, any>;

const ParetoPrinciple: React.FC<ParetoPrincipleProps> = ({
  backgroundColor = "#16192b",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "THE PARETO PRINCIPLE",
  leftTitle = "EFFORTS",
  rightTitle = "RESULTS",
  primaryColor = "#ffffff",
  secondaryColor = "#b29cf5",
  sliceTextColor = "#111111",
  titleColor = "#ffffff",
  explodeDistance = 35,
  titleFontSize = 96,
  labelFontSize = 48,
  sliceFontSize = 76,
}) => {

  useFontLoader(["Poppins"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Title Animations
  const titleScale = spring({
    frame: frame - 5,
    fps,
    config: { damping: 12, mass: 0.8 }
  });
  
  const titleOpacity = interpolate(frame, [5, 15], [0, 1], { extrapolateRight: "clamp" });

  // Label Animations
  const labelOpacity = interpolate(frame, [15, 25], [0, 1], { extrapolateRight: "clamp" });
  const labelY = interpolate(frame, [15, 25], [20, 0], { extrapolateRight: "clamp" });

  const radius = width * 0.125;
  const chartYPosition = height * 0.52; // Shifted up slightly to balance the composition

  const slices = [
    {
      chartId: "efforts",
      chartX: width * 0.3,
      chartY: chartYPosition,
      startTurn: 0.15,
      progressTurn: 0.8,
      color: primaryColor,
      text: "80%",
      textRotationDeg: 0,
      textDistancePct: 0.5,
      explodeMax: 0,
      delay: 20,
    },
    {
      chartId: "efforts",
      chartX: width * 0.3,
      chartY: chartYPosition,
      startTurn: -0.05,
      progressTurn: 0.2,
      color: secondaryColor,
      text: "20%",
      textRotationDeg: 0,
      textDistancePct: 0.65,
      explodeMax: explodeDistance,
      delay: 20,
    },
    {
      chartId: "results",
      chartX: width * 0.7,
      chartY: chartYPosition,
      startTurn: 0.75,
      progressTurn: 0.8,
      color: secondaryColor,
      text: "80%",
      textRotationDeg: 0,
      textDistancePct: 0.5,
      explodeMax: 0,
      delay: 35,
    },
    {
      chartId: "results",
      chartX: width * 0.7,
      chartY: chartYPosition,
      startTurn: 0.55,
      progressTurn: 0.2,
      color: primaryColor,
      text: "20%",
      textRotationDeg: 0,
      textDistancePct: 0.65,
      explodeMax: explodeDistance,
      delay: 35,
    }
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Poppins" }}>
      
      {/* Title */}
      <div style={{
        position: "absolute",
        top: height * 0.12,
        width: "100%",
        display: "flex",
        justifyContent: "center",
        alignItems: "center"
      }}>
        <h1 style={{
          margin: 0,
          fontSize: titleFontSize,
          fontWeight: 900,
          color: titleColor,
          textTransform: "uppercase",
          letterSpacing: width * 0.005,
          textShadow: `0px 0px ${width * 0.015}px ${titleColor}`,
          opacity: titleOpacity,
          transform: `scale(${titleScale})`,
          transition: "none"
        }}>
          {titleText}
        </h1>
      </div>

      {/* Left Label */}
      <div style={{
        position: "absolute",
        top: height * 0.82,
        left: width * 0.3 - width * 0.2,
        width: width * 0.4,
        textAlign: "center",
        fontSize: labelFontSize,
        fontWeight: 800,
        color: titleColor,
        opacity: labelOpacity,
        transform: `translateY(${labelY}px)`,
        transition: "none"
      }}>
        {leftTitle}
      </div>

      {/* Right Label */}
      <div style={{
        position: "absolute",
        top: height * 0.82,
        left: width * 0.7 - width * 0.2,
        width: width * 0.4,
        textAlign: "center",
        fontSize: labelFontSize,
        fontWeight: 800,
        color: titleColor,
        opacity: labelOpacity,
        transform: `translateY(${labelY}px)`,
        transition: "none"
      }}>
        {rightTitle}
      </div>

      {/* Pie Charts */}
      {slices.map((slice, index) => {
        const middleTurn = slice.startTurn + slice.progressTurn / 2;
        const angleRad = (middleTurn * 360 - 90) * (Math.PI / 180);

        const sliceProgress = spring({
          frame: frame - slice.delay,
          fps,
          config: { damping: 14 }
        });

        const explodeProgress = spring({
          frame: frame - slice.delay - 15,
          fps,
          config: { damping: 12 }
        });

        const textScaleAnim = spring({
          frame: frame - slice.delay - 20,
          fps,
          config: { damping: 12 }
        });

        const dx = Math.cos(angleRad) * slice.explodeMax * explodeProgress;
        const dy = Math.sin(angleRad) * slice.explodeMax * explodeProgress;

        const actualProgress = slice.progressTurn * sliceProgress;
        
        const textRadius = radius * slice.textDistancePct;
        const textDx = Math.cos(angleRad) * textRadius;
        const textDy = Math.sin(angleRad) * textRadius;

        return (
          <AbsoluteFill
            key={index}
            style={{
              justifyContent: "center",
              alignItems: "center",
              transform: `translate(${slice.chartX - width / 2 + dx}px, ${slice.chartY - height / 2 + dy}px)`,
              transition: "none"
            }}
          >
            <Pie
              radius={radius}
              progress={actualProgress}
              rotation={slice.startTurn * Math.PI * 2}
              fill={slice.color}
              stroke={backgroundColor}
              strokeWidth={radius * 0.05}
            />
            
            <div style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              transform: `translate(-50%, -50%) translate(${textDx}px, ${textDy}px) rotate(${slice.textRotationDeg}deg) scale(${textScaleAnim})`,
              opacity: textScaleAnim > 0 ? 1 : 0,
              color: sliceTextColor,
              fontSize: sliceFontSize,
              fontWeight: 800,
              pointerEvents: "none",
              transition: "none"
            }}>
              {slice.text}
            </div>
          </AbsoluteFill>
        );
      })}

    </AbsoluteFill>
  );
};

export default ParetoPrinciple;